UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 29, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 30, 15, NULL::text),(3, 166, 10, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 180, 91, NULL::text),(6,0,0,E'a) Cada circuito debe iluminar todas las lámparas de ese circuito cuando el interruptor correspondiente está en la posición "ON" (encendido) y cada luz indicadora debe funcionar correctamente.'),(7, 473, 1365, NULL::text),(8,0,0,E'Todos los vehículos deben contar con un mínimo de dos luces rojas, traseras y funcionales, montadas en la parte posterior del vehículo. - A una altura de entre 380 mm. y 1.8 m. (15-72") por encima de la superficie del camino.'),(9, 2068, 1570, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='6d49aca5-c2c8-5a48-9c69-7c88adab773a' AND md5(a.contenido)='b490884598340c46994acc286b091c69' RETURNING a.id,md5(a.contenido) hash;